import{_ as a,o as i,c as t,a6 as s}from"./chunks/framework.CKIbuWFA.js";const u=JSON.parse('{"title":"プラグイン開発の概要","description":"","frontmatter":{"title":"プラグイン開発の概要","docId":"developer.plugins.index","translationKey":"developer.plugins.index","locale":"ja","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"690689449dfe463405cff0ea6b3a33979249bbe68c598ee7e8ca862eedd704dc","translationRevision":"3005a725ee4752a5afa7ed48b02b426d806faf92442c62266cbcf9dcf1457eef","order":240},"headers":[],"relativePath":"ja/developer/plugins/index.md","filePath":"ja/developer/plugins/index.md","lastUpdated":1794611623000}'),l={name:"ja/developer/plugins/index.md"};function n(r,e,o,p,d,h){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="plugin-development-overview" tabindex="-1">プラグイン開発の概要 <a class="header-anchor" href="#plugin-development-overview" aria-label="Permalink to &quot;プラグイン開発の概要 {#plugin-development-overview}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目的と前提条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>目的の連携を実現する最小のプラグイン境界を選びます。TikTools は組み込み、ユーザー、開発用ルートから実行パッケージを検出します。パッケージ追加のため特定プラグインをホストへ再コンパイルする必要はありません。対応する devkit/SDK と非公開の開発プロファイルで実処理を試します。</p><h2 id="follow-the-authoring-path" tabindex="-1">作成の流れ <a class="header-anchor" href="#follow-the-authoring-path" aria-label="Permalink to &quot;作成の流れ {#follow-the-authoring-path}&quot;">​</a></h2><ol><li><a href="./quickstart.html">クイックスタート</a> で分離パッケージのひな型を作り、検証・ビルドします。</li><li>拡張子だけでなく、ネイティブ依存と信頼に基づき<a href="./runtimes.html">ランタイム</a> を選びます。</li><li>ホストが処理を確認し設定を描画できるよう<a href="./permissions-ui.html">権限と UI</a> を宣言します。</li><li>完全性、発行者の信頼、更新方針には<a href="./packaging-registry.html">パッケージとレジストリ</a> を使います。</li></ol><p>低水準の Rust の正本は <code>crates/tiktools-plugin-api</code> で、マニフェスト検証、プロトコル、UI 契約を持ちます。<code>crates/tiktools-plugin-sdk</code> は Rust 作成 API、<code>packages/plugin-sdk</code> は TypeScript ヘルパーと<a href="https://github.com/nglmercer/TikTools-app/blob/remake/packages/plugin-sdk/plugin.schema.json" target="_blank" rel="noreferrer">エディタースキーマ</a> を提供します。読み込みはフロントエンドではなく <code>crates/tiktools-plugin-loader</code> が担当します。</p><h2 id="understand-contributions" tabindex="-1">提供できる機能 <a class="header-anchor" href="#understand-contributions" aria-label="Permalink to &quot;提供できる機能 {#understand-contributions}&quot;">​</a></h2><p>アクションは型付き結果を通して副作用を要求します。イベントソースはトリガーを公開し、オブザーバーは安定した <code>{topic,data}</code> ドメイン包みを上限付きで受信します。プロセッサーは期限、決定的な結合、健全性の分離の下で、副作用のない証拠を <code>event.intel</code> に追加します。宣言的な設定・アクションはホストが通常の設定画面を描画できます。独自のコンパイル済みページは専用フレーム・ウィンドウ内の制限付きブローカーを使い、スクリプトはメイン Vue ランタイムに入りません。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tiktools-plugin-api</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span></span></code></pre></div><p>これはホスト・SDK の対象検査で、任意の外部パッケージを検証するものではありません。</p><h2 id="expected-result-and-status" tabindex="-1">期待される結果と提供状況 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;期待される結果と提供状況 {#expected-result-and-status}&quot;">​</a></h2><p>native、process、declarative、QuickJS ベースの <code>napi-vm</code> は実装済みです。WASM は任意の枠で、通常ビルドに汎用エンジンはありません。連携例は別の <a href="https://github.com/nglmercer/plugins-example-tiktools" target="_blank" rel="noreferrer">plugins-example-tiktools リポジトリ</a> にあります。旧文書のソース名だけで同梱製品機能とは判断できません。</p><h2 id="recovery" tabindex="-1">問題が起きたとき <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;問題が起きたとき {#recovery}&quot;">​</a></h2><p>検出失敗ではマニフェスト互換性、ルート優先順位、対象、入口パスを確認します。要求が拒否されたらホストを迂回せず宣言済み・付与済み機能を確認します。結果不明の起動は置換前に照合します。native/process は OS レベルの信頼制限を持ち、ランタイム名だけではサンドボックスになりません。</p>`,14)])])}const k=a(l,[["render",n]]);export{u as __pageData,k as default};
